oxy_webhelp_navlinks = {"report_schedules-d39536e65510":{"topics":[{"title":"Creating report schedules","shortdesc":"<p class=\"shortdesc\">Create and store the schedule information for a report on the Reports page. You can         use this stored schedule information when you want to send the report to the selected email         addresses at specific intervals. <\/p>","href":"saas\/common\/creating_a_report_schedule.html","attributes":{"data-id":"creating_a_report_schedule"},"menu":{"hasChildren":false},"tocID":"creating_a_report_schedule-d39536e65524","topics":[]},{"title":"Editing report schedules","shortdesc":"<p class=\"shortdesc\">Edit an existing report schedule to change and store the name of the report schedule,         subscription frequency and time, and the email recipient.<\/p>","href":"saas\/common\/editing_a_report_schedule.html","attributes":{"data-id":"editing_a_report_schedule"},"menu":{"hasChildren":false},"tocID":"editing_a_report_schedule-d39536e65535","topics":[]}]}};